CREATE TABLE PERSONS (
  PERSON_ID INTEGER NOT NULL,
  BURIAL_ID INTEGER NOT NULL,
  SITE_ID INTEGER NOT NULL,
  PERSON_BONES BOOLEAN NOT NULL,
  PERSON_GENDER VARCHAR(3) NOT NULL CHECK (PERSON_GENDER IN ('M','F','N/A')),
  PERSON_AGE VARCHAR(3) NOT NULL CHECK (PERSON_AGE IN ('A','C','N/A')),
  PERSON_MAIN_NOT VARCHAR(3) NOT NULL CHECK (PERSON_MAIN_NOT IN ('M','S','I','N/A')),
  PERSON_POSITION VARCHAR(3) NOT NULL CHECK (PERSON_POSITION IN ('C','E','N/A')),
  PERSON_BED_COFFIN VARCHAR(5) NOT NULL CHECK (PERSON_BED_COFFIN IN ('B','C','S','M','Ca','Ca/C','N/A')),
  PERSON_MUMMY BOOLEAN NOT NULL,
  PERSON_NAME VARCHAR(50) ,
  PERSON_RELATIONS VARCHAR(45),
  PERSON_TITLE VARCHAR(20),
  PRIMARY KEY (PERSON_ID),
  CONSTRAINT FK_PERSON_BURIAL FOREIGN KEY (BURIAL_ID) REFERENCES BURIALS ON DELETE RESTRICT,
  CONSTRAINT FK_PERSON_SITE FOREIGN KEY (SITE_ID) REFERENCES SITES ON DELETE RESTRICT
);
